1	package main
2	
3	import (
4		"archive/zip"
5		"bytes"
6		"crypto/sha256"
7		"encoding/hex"
8		"encoding/json"
9		"errors"
10		"flag"
11		"fmt"
12		"io"
13		"os"
14		"path/filepath"
15		"regexp"
16		"sort"
17		"strings"
18	)
19	
20	// 离线资产迁移包：把所选资产及其全部关联数据连同每条附件索引指向的资料
21	// 文件内容打包为单个 .zip 迁移包（export），日后可在尚不存在的新数据目录
22	// 整包还原（restore），还原后资料为目标目录内的独立副本，脱离源目录。
23	//
24	// 设计约束（与全工具一致）：仅用 Go 标准库；单进程顺序调用；不依赖任何
25	// 外部服务；源台账与原资料只读；失败不留成品包或目标目录，输入字节保持，
26	// 恢复条件后可用原包重试。
27	//
28	// 包内布局（全部为普通文件成员，不允许目录、链接，不允许越界成员名）：
29	//
30	//	caretrack.json          所选数据的台账（storeData 的 JSON，与日常保存同构）
31	//	files/f000001 ...       资料文件内容，每条附件索引一个独立成员
32	//	manifest.json           清单：包格式版本、台账与每份资料的大小及 SHA-256
33	//
34	// 同一路径的多条附件索引各占一个成员，保持独立；已撤销索引的资料同样打包。
35	// 资料成员名是包内生成名，与资料原路径无关；原绝对路径只存在于台账记录中，
36	// 还原时不会按它访问外部任何文件。
37	const (
38		migrateMagic        = "caretrack-migration-package"
39		migrateVersion      = 1
40		migrateManifestName = "manifest.json"
41		migrateLedgerName   = dataFileName
42		migrateFilesDir     = "files"
43		// restoreAttachDir 是还原后目标数据目录内资料副本所在的子目录。
44		restoreAttachDir = "attachments"
45	)
46	
47	// migrateFileMeta 描述包内一个资料成员与一条附件索引的映射及内容校验值。
48	type migrateFileMeta struct {
49		AttachmentID string `json:"attachment_id"`
50		Member       string `json:"member"`
51		Size         int64  `json:"size"`
52		SHA256       string `json:"sha256"`
53	}
54	
55	// migrateManifest 为迁移包清单：台账与每份资料的内容校验值，以及汇总数量。
56	type migrateManifest struct {
57		Format          string            `json:"format"`
58		Version         int               `json:"version"`
59		Ledger          string            `json:"ledger"`
60		LedgerSize      int64             `json:"ledger_size"`
61		LedgerSHA256    string            `json:"ledger_sha256"`
62		Files           []migrateFileMeta `json:"files"`
63		AssetCount      int               `json:"asset_count"`
64		AttachmentCount int               `json:"attachment_count"`
65	}
66	
67	// exportOutcome 为一次成功打包的结果摘要。
68	type exportOutcome struct {
69		packagePath string
70		assetIDs    []string
71		attachments int
72	}
73	
74	// restoreOutcome 为一次成功还原的结果摘要。
75	type restoreOutcome struct {
76		targetDir   string
77		assets      int
78		attachments int
79	}
80	
81	// fileMemberName 生成第 i（从 1 起）个资料成员的包内名称。
82	func fileMemberName(i int) string {
83		return fmt.Sprintf("%s/f%06d", migrateFilesDir, i)
84	}
85	
86	var fileMemberPattern = regexp.MustCompile(`^files/f[0-9]+$`)
87	
88	// sha256Hex 返回数据的 SHA-256 小写十六进制摘要。
89	func sha256Hex(data []byte) string {
90		sum := sha256.Sum256(data)
91		return hex.EncodeToString(sum[:])
92	}
93	
94	// dedupeStrings 按首次出现顺序去重。
95	func dedupeStrings(in []string) []string {
96		seen := map[string]bool{}
97		out := make([]string, 0, len(in))
98		for _, v := range in {
99			if !seen[v] {
100				seen[v] = true
101				out = append(out, v)
102			}
103		}
104		return out
105	}
106	
107	// selectLedgerData 从源台账中抽取所选资产及其全部工单、请求绑定、履历、
108	// 保养计划、备件领用记录与附件索引，组成一份独立的新台账数据。编号、序号、
109	// 计数器与全部业务内容原样保留，不做任何重编号。返回的切片均为新分配，
110	// 修改结果不会影响源台账。第三返回值为按登记履历序号排序的所选附件索引。
111	func selectLedgerData(src *store, ids []string) (*storeData, map[string]bool, []*Attachment) {
112		selected := map[string]bool{}
113		for _, id := range ids {
114			selected[id] = true
115		}
116		d := newStoreData()
117		for _, a := range src.data.Assets {
118			if selected[a.ID] {
119				na := *a
120				d.Assets = append(d.Assets, &na)
121			}
122		}
123		ticketIDs := map[string]bool{}
124		for _, t := range src.data.Tickets {
125			if selected[t.AssetID] {
126				nt := *t
127				d.Tickets = append(d.Tickets, &nt)
128				ticketIDs[t.ID] = true
129			}
130		}
131		for _, r := range src.data.Requests {
132			if ticketIDs[r.TicketID] {
133				d.Requests = append(d.Requests, r)
134			}
135		}
136		for _, e := range src.data.Events {
137			if selected[e.AssetID] {
138				d.Events = append(d.Events, e)
139			}
140		}
141		for _, p := range src.data.Plans {
142			if selected[p.AssetID] {
143				np := *p
144				d.Plans = append(d.Plans, &np)
145			}
146		}
147		for _, p := range src.data.Parts {
148			if ticketIDs[p.TicketID] {
149				np := *p
150				d.Parts = append(d.Parts, &np)
151			}
152		}
153		for _, a := range src.data.Attachments {
154			if ticketIDs[a.TicketID] {
155				na := *a
156				d.Attachments = append(d.Attachments, &na)
157			}
158		}
159		// 计数器原样保留：迁移包内各类编号、履历序号与计数器均与源一致。
160		d.NextTicketSeq = src.data.NextTicketSeq
161		d.NextPartSeq = src.data.NextPartSeq
162		d.NextAttachSeq = src.data.NextAttachSeq
163	
164		regSeqs := src.attachRegSeqs()
165		attachments := make([]*Attachment, len(d.Attachments))
166		copy(attachments, d.Attachments)
167		sort.SliceStable(attachments, func(i, j int) bool {
168			return regSeqs[attachments[i].ID] < regSeqs[attachments[j].ID]
169		})
170		return d, ticketIDs, attachments
171	}
172	
173	// buildMigrationZip 序列化台账并把每份资料连同清单写入 zip。资料内容由
174	// contents 提供（按 attachments 顺序，每条索引一项；同路径多条索引各自
175	// 独立）。zip 先写入 w 指向的临时文件，成功后由调用方原子改名发布。
176	func buildMigrationZip(w io.Writer, ledger []byte, assetCount int, attachments []*Attachment, contents [][]byte) error {
177		zw := zip.NewWriter(w)
178		writeMember := func(name string, data []byte) error {
179			fh := &zip.FileHeader{
180				Name:   name,
181				Method: zip.Deflate,
182			}
183			fh.SetMode(0o644)
184			f, err := zw.CreateHeader(fh)
185			if err != nil {
186				return err
187			}
188			if _, err := f.Write(data); err != nil {
189				return err
190			}
191			return nil
192		}
193		if err := writeMember(migrateLedgerName, ledger); err != nil {
194			return fmt.Errorf("写入台账成员失败: %w", err)
195		}
196		metas := make([]migrateFileMeta, 0, len(attachments))
197		for i, a := range attachments {
198			name := fileMemberName(i + 1)
199			if err := writeMember(name, contents[i]); err != nil {
200				return fmt.Errorf("写入资料成员失败（附件编号 %s）: %w", a.ID, err)
201			}
202			metas = append(metas, migrateFileMeta{
203				AttachmentID: a.ID,
204				Member:       name,
205				Size:         int64(len(contents[i])),
206				SHA256:       sha256Hex(contents[i]),
207			})
208		}
209		manifest := migrateManifest{
210			Format:          migrateMagic + "/1",
211			Version:         migrateVersion,
212			Ledger:          migrateLedgerName,
213			LedgerSize:      int64(len(ledger)),
214			LedgerSHA256:    sha256Hex(ledger),
215			Files:           metas,
216			AssetCount:      assetCount,
217			AttachmentCount: len(metas),
218		}
219		var mbuf bytes.Buffer
220		enc := json.NewEncoder(&mbuf)
221		enc.SetIndent("", "  ")
222		if err := enc.Encode(manifest); err != nil {
223			return fmt.Errorf("编码清单失败: %w", err)
224		}
225		if err := writeMember(migrateManifestName, mbuf.Bytes()); err != nil {
226			return fmt.Errorf("写入清单成员失败: %w", err)
227		}
228		if err := zw.Close(); err != nil {
229			return fmt.Errorf("写入迁移包失败: %w", err)
230		}
231		return nil
232	}
233	
234	// exportPackage 把 dataDir 中所选资产打包到 packagePath。源台账与原资料
235	// 只读；包文件路径已存在、资产未知、源台账矛盾、任一资料不是可读普通文件
236	// 或读写失败时整次拒绝，不留下成品包，也不修改源目录任何字节。
237	func exportPackage(dataDir, packagePath string, assetIDs []string) (*exportOutcome, error) {
238		absPkg, err := filepath.Abs(packagePath)
239		if err != nil {
240			return nil, fmt.Errorf("无法解析迁移包路径 %q: %w", packagePath, err)
241		}
242		// 已有包文件（含目录、符号链接等任何同名路径）不得覆盖。
243		if _, err := os.Lstat(absPkg); err == nil {
244			return nil, fmt.Errorf("迁移包文件 %s 已存在，拒绝覆盖，请另选路径", absPkg)
245		} else if !errors.Is(err, os.ErrNotExist) {
246			return nil, fmt.Errorf("无法访问迁移包路径 %s: %w", absPkg, err)
247		}
248	
249		// 源台账必须已存在并通过整库一致性检查；源始终只读。
250		src, err := openSourceStore(dataDir)
251		if err != nil {
252			return nil, err
253		}
254		ids := dedupeStrings(assetIDs)
255		for _, id := range ids {
256			if src.findAsset(id) == nil {
257				return nil, fmt.Errorf("%w: 源台账中不存在资产编号 %q", errNotFound, id)
258			}
259		}
260	
261		d, _, attachments := selectLedgerData(src, ids)
262		if err := validateData(d); err != nil {
263			return nil, fmt.Errorf("所选数据的业务关联校验失败，拒绝打包: %w", err)
264		}
265	
266		// 每条附件索引（含已撤销）指向的资料当前都必须是可读普通文件；同路径的
267		// 多条索引逐一独立读取，各成一个成员。任一不可用则整次拒绝，不打包。
268		contents := make([][]byte, len(attachments))
269		for i, a := range attachments {
270			if err := checkAttachFile(a.Path); err != nil {
271				return nil, fmt.Errorf("附件编号 %s 指向的资料不可打包: %v", a.ID, err)
272			}
273			raw, rerr := os.ReadFile(a.Path)
274			if rerr != nil {
275				return nil, fmt.Errorf("读取附件编号 %s 的资料 %s 失败: %w", a.ID, a.Path, rerr)
276			}
277			contents[i] = raw
278		}
279	
280		ledger, err := encodeLedger(d)
281		if err != nil {
282			return nil, err
283		}
284		assetCount := len(d.Assets)
285	
286		// 先写同目录临时文件，全部成功并 Sync 后 rename 发布；任何失败都删除
287		// 临时文件，绝不在目标路径留下成品包或半成品。
288		dir := filepath.Dir(absPkg)
289		if err := os.MkdirAll(dir, 0o755); err != nil {
290			return nil, fmt.Errorf("创建迁移包所在目录失败: %w", err)
291		}
292		tmp, err := os.CreateTemp(dir, ".caretrack-pkg-*.zip.tmp")
293		if err != nil {
294			return nil, fmt.Errorf("创建临时迁移包失败: %w", err)
295		}
296		tmpName := tmp.Name()
297		cleanup := func() { _ = os.Remove(tmpName) }
298		if err := buildMigrationZip(tmp, ledger, assetCount, attachments, contents); err != nil {
299			_ = tmp.Close()
300			cleanup()
301			return nil, err
302		}
303		if err := tmp.Sync(); err != nil {
304			_ = tmp.Close()
305			cleanup()
306			return nil, fmt.Errorf("写入迁移包失败: %w", err)
307		}
308		if err := tmp.Close(); err != nil {
309			cleanup()
310			return nil, fmt.Errorf("写入迁移包失败: %w", err)
311		}
312		if err := os.Rename(tmpName, absPkg); err != nil {
313			cleanup()
314			return nil, fmt.Errorf("保存迁移包失败: %w", err)
315		}
316		out := &exportOutcome{
317			packagePath: absPkg,
318			assetIDs:    ids,
319			attachments: len(attachments),
320		}
321		return out, nil
322	}
323	
324	// encodeLedger 以与 store.save 相同的缩进 JSON 形式编码台账数据。
325	func encodeLedger(d *storeData) ([]byte, error) {
326		d.EventsJSON = make([]eventJSON, len(d.Events))
327		for i, e := range d.Events {
328			d.EventsJSON[i] = e.toJSON()
329		}
330		if err := validateData(d); err != nil {
331			return nil, fmt.Errorf("待打包数据未通过一致性检查: %w", err)
332		}
333		var buf bytes.Buffer
334		enc := json.NewEncoder(&buf)
335		enc.SetIndent("", "  ")
336		if err := enc.Encode(d); err != nil {
337			return nil, fmt.Errorf("编码台账失败: %w", err)
338		}
339		return buf.Bytes(), nil
340	}
341	
342	// decodePackageLedger 解析包内台账 JSON 并转换履历、补齐旧库缺省段，
343	// 不做任何写盘。
344	func decodePackageLedger(raw []byte) (*storeData, error) {
345		var d storeData
346		if err := json.Unmarshal(raw, &d); err != nil {
347			return nil, fmt.Errorf("包内台账无法解析: %w", err)
348		}
349		if d.EventsJSON != nil {
350			d.Events = make([]Event, len(d.EventsJSON))
351			for i, ej := range d.EventsJSON {
352				ev, err := ej.toEvent()
353				if err != nil {
354					return nil, fmt.Errorf("包内台账履历无效: %w", err)
355				}
356				d.Events[i] = ev
357			}
358		}
359		if d.Plans == nil {
360			d.Plans = []*Plan{}
361		}
362		if d.Parts == nil {
363			d.Parts = []*PartWithdrawal{}
364		}
365		if d.NextPartSeq == 0 && len(d.Parts) == 0 {
366			d.NextPartSeq = 1
367		}
368		if d.Attachments == nil {
369			d.Attachments = []*Attachment{}
370		}
371		if d.NextAttachSeq == 0 && len(d.Attachments) == 0 {
372			d.NextAttachSeq = 1
373		}
374		return &d, nil
375	}
376	
377	// readZipMember 读取一个 zip 成员的全部内容。
378	func readZipMember(f *zip.File) ([]byte, error) {
379		rc, err := f.Open()
380		if err != nil {
381			return nil, err
382		}
383		defer rc.Close()
384		return io.ReadAll(rc)
385	}
386	
387	// verifyPackage 完整核对迁移包：包格式与版本、成员集合（无缺失、额外、重复
388	// 成员）、成员类型（仅普通文件，拒绝目录与链接）、成员名（拒绝越界路径）、
389	// 台账格式与业务关联、资料映射、实际成员与内容校验值。任何问题都返回说明
390	// 原因的错误。核对全程只读包文件，不写出任何内容。
391	//
392	// 返回台账数据、附件索引到资料成员名的映射与成员内容（键为成员名）。
393	func verifyPackage(zr *zip.Reader) (*storeData, map[string]string, map[string][]byte, error) {
394		// 成员清单核对：名称唯一、仅普通文件、成员名不越界。
395		members := map[string]*zip.File{}
396		for _, f := range zr.File {
397			name := filepath.ToSlash(f.Name)
398			if name == "" || strings.HasPrefix(name, "/") || strings.HasPrefix(name, "../") ||
399				name == ".." || strings.Contains(name, "/../") || strings.HasSuffix(name, "/..") ||
400				strings.Contains(name, "\\") {
401				return nil, nil, nil, fmt.Errorf("迁移包含有越界成员路径 %q，整包拒绝", f.Name)
402			}
403			if !f.Mode().IsRegular() {
404				return nil, nil, nil, fmt.Errorf("迁移包成员 %s 不是普通文件（拒绝目录或链接成员）", name)
405			}
406			if members[name] != nil {
407				return nil, nil, nil, fmt.Errorf("迁移包成员 %s 重复，整包拒绝", name)
408			}
409			members[name] = f
410		}
411	
412		manifestFile := members[migrateManifestName]
413		if manifestFile == nil {
414			return nil, nil, nil, fmt.Errorf("迁移包缺少清单成员 %s", migrateManifestName)
415		}
416		manifestRaw, err := readZipMember(manifestFile)
417		if err != nil {
418			return nil, nil, nil, fmt.Errorf("读取清单失败: %w", err)
419		}
420		var manifest migrateManifest
421		// 宽容解析（忽略未知字段）：包的版本判断必须优先于字段差异，未来版本的
422		// 包须报“未知版本”原因，而不是笼统的格式错误。包内实际成员集合另按
423		// 严格枚举核对，未知字段不会产生任何成员或写出。
424		if err := json.Unmarshal(manifestRaw, &manifest); err != nil {
425			return nil, nil, nil, fmt.Errorf("清单格式无效: %w", err)
426		}
427		if manifest.Format != migrateMagic+"/1" {
428			return nil, nil, nil, fmt.Errorf("未知迁移包格式 %q（本工具支持 %s/1）", manifest.Format, migrateMagic)
429		}
430		if manifest.Version != migrateVersion {
431			return nil, nil, nil, fmt.Errorf("未知迁移包版本 %d：本工具仅支持版本 %d，整包拒绝", manifest.Version, migrateVersion)
432		}
433	
434		// 清单内资料映射自洽：附件编号与成员名均唯一，成员名合法。
435		wantFiles := map[string]bool{}
436		wantAttach := map[string]bool{}
437		for _, fm := range manifest.Files {
438			if fm.AttachmentID == "" || fm.Member == "" || fm.SHA256 == "" {
439				return nil, nil, nil, fmt.Errorf("清单中存在字段不完整的资料条目")
440			}
441			if wantAttach[fm.AttachmentID] {
442				return nil, nil, nil, fmt.Errorf("清单中附件编号 %s 的资料条目重复", fm.AttachmentID)
443			}
444			wantAttach[fm.AttachmentID] = true
445			if wantFiles[fm.Member] {
446				return nil, nil, nil, fmt.Errorf("清单中资料成员 %s 重复", fm.Member)
447			}
448			if !fileMemberPattern.MatchString(fm.Member) {
449				return nil, nil, nil, fmt.Errorf("清单中资料成员名 %q 不合法", fm.Member)
450			}
451			wantFiles[fm.Member] = true
452		}
453	
454		// 实际成员集合必须恰为 {清单, 台账} ∪ 清单所列资料成员：无缺失、无额外。
455		wantMembers := map[string]bool{migrateManifestName: true}
456		if manifest.Ledger != migrateLedgerName {
457			return nil, nil, nil, fmt.Errorf("清单声明的台账成员名为 %q，与约定 %q 不符", manifest.Ledger, migrateLedgerName)
458		}
459		wantMembers[migrateLedgerName] = true
460		for name := range wantFiles {
461			wantMembers[name] = true
462		}
463		if len(members) != len(wantMembers) {
464			return nil, nil, nil, fmt.Errorf("迁移包成员数量不符：应有 %d 个，实际 %d 个（存在缺失或额外成员）",
465				len(wantMembers), len(members))
466		}
467		for name := range wantMembers {
468			if members[name] == nil {
469				return nil, nil, nil, fmt.Errorf("迁移包缺少成员 %s", name)
470			}
471		}
472		for name := range members {
473			if !wantMembers[name] {
474				return nil, nil, nil, fmt.Errorf("迁移包含有清单之外的额外成员 %s", name)
475			}
476		}
477	
478		// 台账内容校验值、格式与整库业务关联。
479		ledgerRaw, err := readZipMember(members[migrateLedgerName])
480		if err != nil {
481			return nil, nil, nil, fmt.Errorf("读取台账成员失败: %w", err)
482		}
483		if int64(len(ledgerRaw)) != manifest.LedgerSize || sha256Hex(ledgerRaw) != manifest.LedgerSHA256 {
484			return nil, nil, nil, fmt.Errorf("台账成员内容损坏：大小或校验值与清单不符")
485		}
486		d, err := decodePackageLedger(ledgerRaw)
487		if err != nil {
488			return nil, nil, nil, err
489		}
490		if err := validateData(d); err != nil {
491			return nil, nil, nil, fmt.Errorf("包内台账业务关联校验失败: %w", err)
492		}
493		// 清单汇总数量须与台账实际成员一致。
494		if manifest.AssetCount != len(d.Assets) {
495			return nil, nil, nil, fmt.Errorf("清单资产数量 %d 与台账实际 %d 不符",
496				manifest.AssetCount, len(d.Assets))
497		}
498		if manifest.AttachmentCount != len(d.Attachments) {
499			return nil, nil, nil, fmt.Errorf("清单附件索引数量 %d 与台账实际 %d 不符",
500				manifest.AttachmentCount, len(d.Attachments))
501		}
502	
503		// 资料映射核对：每条附件索引恰有一个资料成员，每个资料成员恰对应一条
504		// 附件索引；成员内容的大小与 SHA-256 与清单一致（zip 读取本身已校验 CRC）。
505		attachByID := map[string]*Attachment{}
506		for _, a := range d.Attachments {
507			attachByID[a.ID] = a
508		}
509		if len(attachByID) != len(d.Attachments) {
510			return nil, nil, nil, fmt.Errorf("包内台账附件编号重复")
511		}
512		if len(manifest.Files) != len(d.Attachments) {
513			return nil, nil, nil, fmt.Errorf("资料成员数量（%d）与附件索引数量（%d）不符",
514				len(manifest.Files), len(d.Attachments))
515		}
516		attachMember := map[string]string{}
517		contents := map[string][]byte{}
518		for _, fm := range manifest.Files {
519			if attachByID[fm.AttachmentID] == nil {
520				return nil, nil, nil, fmt.Errorf("资料成员 %s 对应的附件编号 %s 在台账中不存在",
521					fm.Member, fm.AttachmentID)
522			}
523			raw, err := readZipMember(members[fm.Member])
524			if err != nil {
525				return nil, nil, nil, fmt.Errorf("读取资料成员 %s 失败: %w", fm.Member, err)
526			}
527			if int64(len(raw)) != fm.Size || sha256Hex(raw) != fm.SHA256 {
528				return nil, nil, nil, fmt.Errorf("资料成员 %s（附件编号 %s）内容损坏：大小或校验值不符",
529					fm.Member, fm.AttachmentID)
530			}
531			attachMember[fm.AttachmentID] = fm.Member
532			contents[fm.Member] = raw
533		}
534		return d, attachMember, contents, nil
535	}
536	
537	// writeAtomicFile 在 dir 下经临时文件 + rename 原子写入一个普通文件，
538	// 权限 0644；失败由调用方负责清理暂存目录。
539	func writeAtomicFile(path string, data []byte) error {
540		dir := filepath.Dir(path)
541		tmp, err := os.CreateTemp(dir, ".caretrack-restore-*.tmp")
542		if err != nil {
543			return err
544		}
545		tmpName := tmp.Name()
546		if _, err := tmp.Write(data); err != nil {
547			_ = tmp.Close()
548			_ = os.Remove(tmpName)
549			return err
550		}
551		if err := tmp.Sync(); err != nil {
552			_ = tmp.Close()
553			_ = os.Remove(tmpName)
554			return err
555		}
556		if err := tmp.Close(); err != nil {
557			_ = os.Remove(tmpName)
558			return err
559		}
560		if err := os.Chmod(tmpName, 0o644); err != nil {
561			_ = os.Remove(tmpName)
562			return err
563		}
564		if err := os.Rename(tmpName, path); err != nil {
565			_ = os.Remove(tmpName)
566			return err
567		}
568		return nil
569	}
570	
571	// restorePackage 从迁移包在尚不存在的 targetDir 还原数据：先在目标的同级
572	// 暂存目录内建立台账与独立资料副本（附件记录及登记、撤销履历中的路径同步
573	// 替换为副本的绝对路径），全部写入并复核后才整体改名发布为目标目录。任何
574	// 失败都不留下目标目录或部分资料；输入包与原数据字节保持，可用原包重试。
575	func restorePackage(packagePath, targetDir string) (*restoreOutcome, error) {
576		absPkg, err := filepath.Abs(packagePath)
577		if err != nil {
578			return nil, fmt.Errorf("无法解析迁移包路径 %q: %w", packagePath, err)
579		}
580		absTarget, err := filepath.Abs(targetDir)
581		if err != nil {
582			return nil, fmt.Errorf("无法解析目标数据目录 %q: %w", targetDir, err)
583		}
584		// 目标目录（或任何同名路径）已存在即拒绝。
585		if _, err := os.Lstat(absTarget); err == nil {
586			return nil, fmt.Errorf("目标数据目录 %s 已存在，拒绝覆盖，请选择尚不存在的目录", absTarget)
587		} else if !errors.Is(err, os.ErrNotExist) {
588			return nil, fmt.Errorf("无法访问目标数据目录 %s: %w", absTarget, err)
589		}
590	
591		// 迁移包须为可读普通文件；只读打开，绝不写回。
592		pf, err := os.Open(absPkg)
593		if err != nil {
594			return nil, fmt.Errorf("无法打开迁移包 %s: %w", absPkg, err)
595		}
596		fi, err := pf.Stat()
597		if err != nil {
598			_ = pf.Close()
599			return nil, fmt.Errorf("无法读取迁移包 %s: %w", absPkg, err)
600		}
601		if !fi.Mode().IsRegular() {
602			_ = pf.Close()
603			return nil, fmt.Errorf("迁移包 %s 不是普通文件", absPkg)
604		}
605		zr, err := zip.NewReader(pf, fi.Size())
606		if err != nil {
607			_ = pf.Close()
608			return nil, fmt.Errorf("迁移包 %s 不是有效的包格式: %w", absPkg, err)
609		}
610		// 提交前完整核对：格式、版本、业务关联、资料映射、实际成员与校验值。
611		d, attachMember, contents, err := verifyPackage(zr)
612		if err != nil {
613			_ = pf.Close()
614			return nil, err
615		}
616		if err := pf.Close(); err != nil {
617			return nil, fmt.Errorf("读取迁移包失败: %w", err)
618		}
619	
620		// 附件路径替换映射：副本将位于目标目录内的 attachments/ 子目录，文件名
621		// 沿用包内生成名；这些路径均由工具生成，绝不取自包内原绝对路径，也不会
622		// 按原路径访问外部资料。
623		newPath := map[string]string{}
624		for _, a := range d.Attachments {
625			base := filepath.Base(attachMember[a.ID])
626			np := filepath.Join(absTarget, restoreAttachDir, base)
627			newPath[a.ID] = np
628		}
629		for _, a := range d.Attachments {
630			a.Path = newPath[a.ID]
631		}
632		// 登记与撤销履历中的路径同步替换（validateData 已保证履历路径与记录一致，
633		// 替换后其余身份与业务含义保持，不新增任何履历）。
634		for i := range d.Events {
635			e := &d.Events[i]
636			if (e.Kind == eventAttach || e.Kind == eventAttachRevoke) && e.AttachmentID != "" {
637				if np := newPath[e.AttachmentID]; np != "" {
638					e.Path = np
639				}
640			}
641		}
642		if err := validateData(d); err != nil {
643			return nil, fmt.Errorf("替换资料路径后台账校验失败: %w", err)
644		}
645		ledger, err := encodeLedger(d)
646		if err != nil {
647			return nil, err
648		}
649	
650		// 在目标同级建立暂存目录，所有写入完成并复核后整体 rename 发布；
651		// 任何失败都删除暂存目录并确保目标路径不存在。
652		parent := filepath.Dir(absTarget)
653		if err := os.MkdirAll(parent, 0o755); err != nil {
654			return nil, fmt.Errorf("创建目标父目录失败: %w", err)
655		}
656		stage, err := os.MkdirTemp(parent, ".caretrack-restore-*")
657		if err != nil {
658			return nil, fmt.Errorf("创建暂存目录失败: %w", err)
659		}
660		abort := func(err error) (*restoreOutcome, error) {
661			_ = os.RemoveAll(stage)
662			_ = os.RemoveAll(absTarget)
663			return nil, err
664		}
665		if err := os.MkdirAll(filepath.Join(stage, restoreAttachDir), 0o755); err != nil {
666			return abort(fmt.Errorf("创建资料目录失败: %w", err))
667		}
668		if err := writeAtomicFile(filepath.Join(stage, dataFileName), ledger); err != nil {
669			return abort(fmt.Errorf("写入台账失败: %w", err))
670		}
671		// 资料副本：逐份写入，成员名由工具生成，全部限制在暂存目录（发布后即
672		// 目标目录）之内。
673		for _, a := range d.Attachments {
674			member := attachMember[a.ID]
675			dst := filepath.Join(stage, restoreAttachDir, filepath.Base(member))
676			if err := writeAtomicFile(dst, contents[member]); err != nil {
677				return abort(fmt.Errorf("写入资料副本失败（附件编号 %s）: %w", a.ID, err))
678			}
679		}
680		// 发布前在暂存目录内复核：台账可加载且业务自洽，每份资料为与包内一致的
681		// 普通文件（内容校验值相符）。
682		checkStore, err := loadStore(stage, false)
683		if err != nil {
684			return abort(fmt.Errorf("暂存台账复核失败: %w", err))
685		}
686		for _, a := range checkStore.data.Attachments {
687			member := attachMember[a.ID]
688			path := filepath.Join(stage, restoreAttachDir, filepath.Base(member))
689			raw, rerr := os.ReadFile(path)
690			if rerr != nil {
691				return abort(fmt.Errorf("资料副本复核失败（附件编号 %s）: %w", a.ID, rerr))
692			}
693			if sha256Hex(raw) != sha256Hex(contents[member]) {
694				return abort(fmt.Errorf("资料副本（附件编号 %s）复核校验值不符", a.ID))
695			}
696		}
697		// 整体发布：暂存目录原子改名为目标目录。
698		if err := os.Rename(stage, absTarget); err != nil {
699			return abort(fmt.Errorf("发布目标目录失败: %w", err))
700		}
701		// 发布后再复核一次：台账可加载、资料副本为可读普通文件。全部就绪后才
702		// 向调用方报告成功；失败则移除目标目录。
703		final, err := openSourceStore(absTarget)
704		if err != nil {
705			_ = os.RemoveAll(absTarget)
706			return nil, fmt.Errorf("还原后复核失败: %w", err)
707		}
708		for _, a := range final.data.Attachments {
709			if !attachmentReadable(a.Path) {
710				_ = os.RemoveAll(absTarget)
711				return nil, fmt.Errorf("还原后复核失败：附件编号 %s 的资料副本不可读", a.ID)
712			}
713		}
714		return &restoreOutcome{
715			targetDir:   absTarget,
716			assets:      len(final.data.Assets),
717			attachments: len(final.data.Attachments),
718		}, nil
719	}
720	
721	// cmdExport 为“导出迁移包”命令处理：输入数据目录、非空资产编号列表与包
722	// 文件路径。源台账与原资料只读，已有包文件不得覆盖，任何失败不留成品包。
723	func cmdExport(args []string, w io.Writer) error {
724		var opts cmdOptions
725		var packagePath string
726		var assetIDs stringListFlag
727		fs := newFlagSet("export", &opts)
728		fs.StringVar(&packagePath, "package", "", "迁移包文件路径（必填；已存在则拒绝，不会覆盖）")
729		fs.Var(&assetIDs, "asset-id", "要打包的资产编号（必填，可重复；重复编号按一项处理）")
730		if err := parseFlags(fs, args); err != nil {
731			return err
732		}
733		if err := requireFlag(fs, packagePath, "package"); err != nil {
734			return err
735		}
736		if len(assetIDs) == 0 {
737			return &usageError{msg: "命令 export 缺少必填参数 --asset-id（至少一项资产编号）"}
738		}
739		for _, id := range assetIDs {
740			if id == "" {
741				return &usageError{msg: "命令 export 的 --asset-id 不能为空"}
742			}
743		}
744	
745		outcome, err := exportPackage(opts.dataDir, packagePath, []string(assetIDs))
746		if err != nil {
747			return err
748		}
749		fmt.Fprintf(w, "迁移包已生成: %s\n", outcome.packagePath)
750		fmt.Fprintf(w, "所选资产: %d 项（%s）\n", len(outcome.assetIDs), strings.Join(outcome.assetIDs, ", "))
751		fmt.Fprintf(w, "附件索引: %d 条\n", outcome.attachments)
752		return nil
753	}
754	
755	// cmdRestore 为“包还原”命令处理：输入包路径和尚不存在的目标数据目录。
756	// 在目标内建立独立资料副本，路径同步替换为副本绝对路径；失败不留目标。
757	func cmdRestore(args []string, w io.Writer) error {
758		fs := flag.NewFlagSet("restore", flag.ContinueOnError)
759		fs.SetOutput(os.Stdout)
760		fs.Usage = func() {
761			fmt.Fprintf(os.Stdout, "用法: caretrack restore --package 包文件 --target-dir 目录\n\n")
762			fs.PrintDefaults()
763		}
764		var packagePath, targetDir string
765		fs.StringVar(&packagePath, "package", "", "迁移包文件路径（必填）")
766		fs.StringVar(&targetDir, "target-dir", "", "要创建的目标数据目录（必填；必须尚不存在）")
767		if err := parseFlags(fs, args); err != nil {
768			return err
769		}
770		if err := requireFlag(fs, packagePath, "package"); err != nil {
771			return err
772		}
773		if err := requireFlag(fs, targetDir, "target-dir"); err != nil {
774			return err
775		}
776	
777		outcome, err := restorePackage(packagePath, targetDir)
778		if err != nil {
779			return err
780		}
781		fmt.Fprintf(w, "迁移包已还原: %s\n", outcome.targetDir)
782		fmt.Fprintf(w, "资产: %d 项\n", outcome.assets)
783		fmt.Fprintf(w, "附件索引: %d 条\n", outcome.attachments)
784		return nil
785	}
786

