474	// pkgEntry 为测试用 zip 成员描述；mode 非零时可表达目录或符号链接。
475	type pkgEntry struct {
476		name string
477		data []byte
478		mode os.FileMode
479	}
480	
481	func readPkgEntries(t *testing.T, path string) []pkgEntry {
482		t.Helper()
483		zr, err := zip.OpenReader(path)
484		if err != nil {
485			t.Fatalf("打开迁移包: %v", err)
486		}
487		defer zr.Close()
488		entries := make([]pkgEntry, 0, len(zr.File))
489		for _, f := range zr.File {
490			rc, err := f.Open()
491			if err != nil {
492				t.Fatal(err)
493			}
494			data, err := io.ReadAll(rc)
495			rc.Close()
496			if err != nil {
497				t.Fatal(err)
498			}
499			entries = append(entries, pkgEntry{name: f.Name, data: data, mode: f.Mode()})
500		}
501		return entries
502	}
503	
504	func writePkgEntries(t *testing.T, path string, entries []pkgEntry) {
505		t.Helper()
506		if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
507			t.Fatal(err)
508		}
509		f, err := os.Create(path)
510		if err != nil {
511			t.Fatal(err)
512		}
513		defer f.Close()
514		zw := zip.NewWriter(f)
515		for _, e := range entries {
516			fh := &zip.FileHeader{Name: e.name, Method: zip.Deflate}
517			mode := e.mode
518			if mode == 0 {
519				mode = 0o644
520			}
521			fh.SetMode(mode)
522			w, err := zw.CreateHeader(fh)
523			if err != nil {
524				t.Fatal(err)
525			}
526			if _, err := w.Write(e.data); err != nil {
527				t.Fatal(err)
528			}
529		}
530		if err := zw.Close(); err != nil {
531			t.Fatal(err)
532		}
533	}
534	
535	func findEntry(entries []pkgEntry, name string) *pkgEntry {
536		for i := range entries {
537			if entries[i].name == name {
538				return &entries[i]
539			}
540		}
541		return nil
542	}
543	
544	func withoutEntry(entries []pkgEntry, name string) []pkgEntry {
545		out := make([]pkgEntry, 0, len(entries))
546		for _, e := range entries {
547			if e.name != name {
548				out = append(out, e)
549			}
550		}
551		return out
552	}
