747		// 业务失败：未知资产导出退出 1；不存在的包还原退出 1。
748		if code, _, _ := runCmd("export", "--data-dir", fx.srcDir, "--package", pkg, "--asset-id", "NOPE"); code != 1 {
749			t.Fatalf("未知资产导出应退出 1，得到 %d", code)
750		}
751		if code, _, _ := runCmd("restore", "--package", filepath.Join(work, "missing.zip"),
752			"--target-dir", filepath.Join(work, "t1")); code != 1 {
753			t.Fatalf("包不存在还原应退出 1，得到 %d", code)
754		}
755	
756		// 导出成功并显示资产与附件索引数量。
757		code, o, _ := runCmd("export", "--data-dir", fx.srcDir, "--package", pkg,
758			"--asset-id", "EQ-A", "--asset-id", "EQ-B")
759		if code != 0 || !strings.Contains(o, "所选资产: 2 项") || !strings.Contains(o, "附件索引: 4 条") {
760			t.Fatalf("导出应成功并显示数量，得到 %d:\n%s", code, o)
761		}
762		// 还原成功并显示数量。
763		target := filepath.Join(work, "restored")
764		code, o, _ = runCmd("restore", "--package", pkg, "--target-dir", target)
765		if code != 0 || !strings.Contains(o, "资产: 2 项") || !strings.Contains(o, "附件索引: 4 条") {
766			t.Fatalf("还原应成功并显示数量，得到 %d:\n%s", code, o)
767		}
768		// 目标已存在退出 1。
769		if code, _, _ := runCmd("restore", "--package", pkg, "--target-dir", target); code != 1 {
770			t.Fatalf("目标已存在应退出 1，得到 %d", code)
771		}
772		// 已有包文件不得覆盖，退出 1。
773		if code, _, _ := runCmd("export", "--data-dir", fx.srcDir, "--package", pkg, "--asset-id", "EQ-D"); code != 1 {
774			t.Fatalf("包文件已存在应退出 1，得到 %d", code)
775		}
776	}
