3	import (
4		"fmt"
5		"math"
6		"os"
7		"sort"
8	)
9	
10	// 维修工单本地资料附件索引。
11	//
12	// 只保存资料文件的引用（登记时解析得到的绝对路径），不复制、不修改、不删除
13	// 资料文件本身。登记输入工单编号、本地文件路径与非空说明；未关闭、已关闭或
14	// 已取消工单均可补充资料。登记时文件须为存在且可读的普通文件；文件日后消失、
15	// 成为目录或不可读仅使引用不可用，不阻止撤销及其他业务，也不参与整库一致性
16	// 校验。每次登记独立生成同目录唯一且不复用的附件编号（A 加补零序号），同路径
17	// 不合并，也不使用报修请求标识去重。
18	//
19	// 撤销输入附件编号与非空理由，保留记录、路径、说明与理由；未知编号、重复撤销
20	// 拒绝，不影响同路径其他索引或后来工单。工单终结不自动撤销附件；已撤销编号
21	// 不能恢复，可重新登记为新索引。登记、撤销各为一次原子保存：校验、编号或履历
22	// 容量不足、读写失败时保留原文件字节，不留下部分记录、不消耗编号，恢复后可重试。
23	
24	// findAttachment 按附件编号查找附件记录，不存在时返回 nil。
25	func (s *store) findAttachment(id string) *Attachment {
26		for _, a := range s.data.Attachments {
27			if a.ID == id {
28				return a
29			}
30		}
31		return nil
32	}
33	
34	// attachRegSeqs 返回每条附件编号对应的登记履历全库序号。附件编号只用于定位
35	// 记录：各条索引的先后由该条唯一登记履历的序号决定，与记录数组位置、编号
36	// 大小及履历时间无关（有效台账允许数组乱序、序号间隔、时间不递增）。
37	func (s *store) attachRegSeqs() map[string]int {
38		seqs := make(map[string]int, len(s.data.Attachments))
39		for _, e := range s.data.Events {
40			if e.Kind == eventAttach {
41				seqs[e.AttachmentID] = e.Seq
42			}
43		}
44		return seqs
45	}
46	
47	// attachmentsOf 按登记先后返回工单的全部附件记录（含已撤销）：顺序由每条
48	// 唯一登记履历的全库序号决定，不使用数组位置或编号大小。
49	func (s *store) attachmentsOf(ticketID string) []*Attachment {
50		seqs := s.attachRegSeqs()
51		out := make([]*Attachment, 0)
52		for _, a := range s.data.Attachments {
53			if a.TicketID == ticketID {
54				out = append(out, a)
55			}
56		}
57		sort.SliceStable(out, func(i, j int) bool { return seqs[out[i].ID] < seqs[out[j].ID] })
58		return out
59	}
