61	// checkAttachFile 校验登记时的资料文件：须为存在且可读的普通文件。
62	func checkAttachFile(path string) error {
63		fi, err := os.Stat(path)
64		if err != nil {
65			return fmt.Errorf("附件文件 %s 不存在或不可访问: %v", path, err)
66		}
67		if !fi.Mode().IsRegular() {
68			return fmt.Errorf("附件路径 %s 不是普通文件", path)
69		}
70		f, err := os.Open(path)
71		if err != nil {
72			return fmt.Errorf("附件文件 %s 不可读: %v", path, err)
73		}
74		return f.Close()
75	}
76	
77	// attachmentReadable 报告资料文件当前是否仍可作为普通文件读取。文件日后
78	// 消失、成为目录或不可读仅使引用不可用，不影响台账一致性与任何业务操作。
79	func attachmentReadable(path string) bool {
80		return checkAttachFile(path) == nil
81	}
82	
83	// appendAttachEvent 以给定序号追加附件履历（登记或撤销）。附件履历属于附件
84	// 记录所在的工单，from/to、保养与备件字段恒为空；content 为附件说明或撤销
85	// 理由，Path 为记录保存的绝对路径。
86	func (s *store) appendAttachEvent(seq int, a *Attachment, kind, content string) {
87		s.data.Events = append(s.data.Events, Event{
88			Seq:          seq,
89			AssetID:      a.AssetID,
90			TicketID:     a.TicketID,
91			Kind:         kind,
92			Content:      content,
93			AttachmentID: a.ID,
94			Path:         a.Path,
