1	package main
2	
3	import (
4		"bytes"
5		"errors"
6		"os"
7		"path/filepath"
8		"sort"
9		"strings"
10		"testing"
11	)
12	
13	// errInjectedRestoreFault 为写入类接缝在真实写入点返回的确定性故障。故障只在
14	// 指定的一次 writeAtomicFile 调用上注入；复制失败用例会先向临时文件写入部分
15	// 真实字节再返回该错误，与真实“写了一半后失败”走完全相同的清理路径。
16	var errInjectedRestoreFault = errors.New("测试注入的确定性写入故障")
17	
18	// restoreStageMarks 记录一次还原实际到达过的阶段，由真实流程在接缝回调中置位。
19	// 负例据此断言“指定阶段确已到达”，且后续阶段未被提前阻断或跳过。
20	type restoreStageMarks struct {
21		mkdirAttach       bool // 已到达暂存内资料目录创建
22		ledgerWrite       bool // 已到达台账原子写入
23		copyCalls         int  // 资料副本 writeAtomicFile 到达次数
24		copySucceededSeen bool // 失败发生前至少一份资料副本已完整落盘
25		partialWritten    bool // 失败的临时文件中已写入部分真实字节
26		preVerify         bool // 已到达发布前复核
27		publish           bool // 已到达目标目录改名发布
28		postVerify        bool // 已到达发布后复核
29	}
30	
31	// restoreFaultCase 描述一个在真实还原操作处确定性触发的中途失败用例。
32	type restoreFaultCase struct {
33		name    string
34		wantErr string // stderr（原因说明）必须包含的片段
35		// hooks 在各用例自己的临时目录上构造接缝；故障通过制造真实文件系统状态
36		// 让真实操作本身失败，或在真实写入点返回一次注入错误。
37		hooks func(t *testing.T, m *restoreStageMarks) *restoreTestHooks
38		// reached 断言指定阶段已到达、且不应到达的阶段确未到达。
39		reached func(t *testing.T, m *restoreStageMarks)
40	}
41	
42	func restoreFaultCases() []restoreFaultCase {
43		return []restoreFaultCase{
44			{
45				name:    "暂存建成后资料目录创建失败",
46				wantErr: "创建资料目录失败",
47				hooks: func(t *testing.T, m *restoreStageMarks) *restoreTestHooks {
48					return &restoreTestHooks{
49						beforeMkdirAttach: func(stage string) {
50							m.mkdirAttach = true
51							// 暂存目录已由真实 MkdirTemp 建成；把它替换成普通文件，
52							// 随后真实的 MkdirAll(stage/attachments) 必以 ENOTDIR 失败。
53							if err := os.Remove(stage); err != nil {
54								t.Fatalf("移除空暂存目录: %v", err)
55							}
56							if err := os.WriteFile(stage, []byte("占位普通文件"), 0o644); err != nil {
57								t.Fatalf("以普通文件占位暂存路径: %v", err)
58							}
59						},
60					}
61				},
62				reached: func(t *testing.T, m *restoreStageMarks) {
63					if !m.mkdirAttach {
64						t.Fatal("应已到达资料目录创建")
65					}
66					if m.ledgerWrite || m.preVerify || m.publish || m.postVerify {
67						t.Fatalf("资料目录创建失败后不应进入后续阶段: %+v", m)
68					}
69				},
70			},
71			{
72				name:    "台账写入失败",
73				wantErr: "写入台账失败",
74				hooks: func(t *testing.T, m *restoreStageMarks) *restoreTestHooks {
75					return &restoreTestHooks{
76						writeFault: func(path string, tmp *os.File, data []byte) error {
77							if filepath.Base(path) != dataFileName {
78								return nil
79							}
80							m.ledgerWrite = true
81							return errInjectedRestoreFault
82						},
83					}
84				},
85				reached: func(t *testing.T, m *restoreStageMarks) {
86					if !m.ledgerWrite {
87						t.Fatal("应已到达台账写入")
88					}
89					if m.copyCalls != 0 || m.preVerify || m.publish || m.postVerify {
90						t.Fatalf("台账写入失败后不应写入资料或进入复核: %+v", m)
91					}
92				},
93			},
94			{
95				name:    "首份副本写好后后续副本写入失败",
96				wantErr: "写入资料副本失败",
97				hooks: func(t *testing.T, m *restoreStageMarks) *restoreTestHooks {
98					return &restoreTestHooks{
99						writeFault: func(path string, tmp *os.File, data []byte) error {
100							if filepath.Base(path) == dataFileName {
101								return nil // 台账写入不受影响
102							}
103							m.copyCalls++
104							if m.copyCalls == 1 {
105								return nil // 第一份资料副本完整写好
106							}
107							// 第二份起：先把一半真实字节写入其临时文件，再令本次写入失败。
